    @EventHandler( payloadType=UpdateOfferEvent.class )
    public void handle( UpdateOfferEvent event) {
    	LOGGER.info("handling UpdateOfferEvent - " + event );
    	
	    Offer entity = new Offer();
            entity.setOfferId( event.getOfferId() );
            entity.setOfferNumber( event.getOfferNumber() );
            entity.setProposedStartDate( event.getProposedStartDate() );
            entity.setBaseSalary( event.getBaseSalary() );
            entity.setSignOnBonus( event.getSignOnBonus() );
            entity.setRequisition( event.getRequisition() );
            entity.setCandidate( event.getCandidate() );
            entity.setApprovedBy( event.getApprovedBy() );
            entity.setContract( event.getContract() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindOffer( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOffer( entity );        
    }
    
