    /**
     * Method to retrieve the Offer via an OfferPrimaryKey.
     * @param 	id Long
     * @return 	Offer
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Offer handle( FindOfferQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getOfferId() );
    }
    
    /**
     * Method to retrieve a collection of all Offers
     *
     * @param	query	FindAllOfferQuery 
     * @return 	List<Offer> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Offer> handle( FindAllOfferQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindOffer,
 * but only if the id matches
 *
 * @param		entity	Offer
 */
	protected void emitFindOffer( Offer entity ) {
		LOGGER.info("handling emitFindOffer" );
		
	    queryUpdateEmitter.emit(FindOfferQuery.class,
	                            query -> query.getFilter().getOfferId().equals(entity.getOfferId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOffer
	 * 
	 * @param		entity	Offer
	 */
	protected void emitFindAllOffer( Offer entity ) {
		LOGGER.info("handling emitFindAllOffer" );
		
	    queryUpdateEmitter.emit(FindAllOfferQuery.class,
	                            query -> true,
	                            entity);
	}

